private static WebpInfo parseWebp(File file) {
    try (InputStream in = new BufferedInputStream(new FileInputStream(file))) {
        byte[] buf = new byte[12];
        if (in.read(buf) != 12) return null;
        if (!isSignature(buf, 0, RIFF) || !isSignature(buf, 8, WEBP)) return null;
        // Read first chunk
        byte[] chunkHeader = new byte[8];
        if (in.read(chunkHeader) != 8) return null;
        String fourcc = new String(chunkHeader, 0, 4, StandardCharsets.US_ASCII);
        int chunkSize = readUInt32(chunkHeader, 4);
        if ("VP8 ".equals(fourcc)) {
            return new WebpInfo(false, false);
        } else if ("VP8L".equals(fourcc)) {
            return new WebpInfo(true, true);
        } else if ("VP8X".equals(fourcc)) {
            // Read flags
            if (chunkSize < 1) return null;
            int flags = in.read();
            if (flags == -1) return null;
            boolean alpha = (flags & 0x10) != 0; // choose bit maybe 0x08
            // skip rest of VP8X payload (chunkSize - 1 bytes) rounded to even
            skip(in, chunkSize - 1 + ((chunkSize) % 2));
            // scan subsequent chunks
            while (true) {
                byte[] ch = new byte[8];
                int read = in.read(ch);
                if (read != 8) break; // end or error
                String cc = new String(ch, 0, 4, StandardCharsets.US_ASCII);
                int size = readUInt32(ch, 4);
                if ("VP8 ".equals(cc)) {
                    return new WebpInfo(false, alpha);
                } else if ("VP8L".equals(cc)) {
                    return new WebpInfo(true, alpha || true);
                } else if ("ALPH".equals(cc)) {
                    alpha = true;
                    skip(in, size + (size % 2));
                } else {
                    skip(in, size + (size % 2));
                }
            }
            return new WebpInfo(false, alpha);
        }
    } catch (IOException e) { return null; }
    return null;
}
```

